import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const l="/assets/ssl-2023121703.CrfSH4_d.png",i="/assets/ssl-2023121704.CqTiwb2b.png",s="/assets/ssl-2023121705.BtOKrBGY.png",d="/assets/ssl-2023121706.CzUKv_lT.png",n="/assets/ssl-2023121707.CKmPtL_U.png",c="/assets/ssl-2023121708.Dky7AxBd.png",h="/assets/336_a0a3ac99-471f-4e72-816b-1169d372d59b.C0E1GFUV.png",g="/assets/ssl-2023121710.BgE5aU5_.png",p="/assets/337_cfb09ba9-75b0-4187-8de5-5bf952ee18c2.B6De757a.png",u="/assets/338_38eecbe8-53cc-42c6-8a64-2cffe5793bca.pHzBBWPJ.png",D=JSON.parse('{"title":"SSL证书验证方式指南","description":"","frontmatter":{"title":"SSL证书验证方式指南"},"headers":[],"relativePath":"ops-knowledge-base/ssl/ssl-certificate-verification-guide.md","filePath":"ops-knowledge-base/ssl/ssl-certificate-verification-guide.md","lastUpdated":1788259091000}'),m={name:"ops-knowledge-base/ssl/ssl-certificate-verification-guide.md"};function b(_,t,x,q,S,f){return a(),e("div",null,[...t[0]||(t[0]=[r('<h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>在 SSL 证书申请过程中，**域名控制权验证（DCV）**用于证明您对域名拥有管理权限。完成 DCV 后，证书通常会在约 30 分钟内签发。</p><table tabindex="0"><thead><tr><th>验证方式</th><th>适用场景</th><th></th></tr></thead><tbody><tr><td><strong>邮件验证</strong></td><td>域名邮箱可接收邮件</td><td>几分钟内</td></tr><tr><td><strong>DNS验证</strong></td><td>可管理域名DNS解析</td><td>解析生效后</td></tr><tr><td><strong>HTTP/HTTPS验证</strong></td><td>可访问网站根目录</td><td>文件上传后</td></tr></tbody></table><blockquote><p>⚠️ <strong>重要提示</strong>：邮箱认证接收邮件的邮箱必须是<strong>客户域名邮箱</strong>或<strong>WHOIS查询到的域名注册邮箱</strong>。所有验证操作需客户自行处理。</p></blockquote><hr><h2 id="二、通用填写规则" tabindex="-1">二、通用填写规则 <a class="header-anchor" href="#二、通用填写规则" aria-label="Permalink to &quot;二、通用填写规则&quot;">​</a></h2><h3 id="_2-1-域名填写规范" tabindex="-1">2.1 域名填写规范 <a class="header-anchor" href="#_2-1-域名填写规范" aria-label="Permalink to &quot;2.1 域名填写规范&quot;">​</a></h3><p>在申请SSL证书时，<strong>Domain信息不能填写IP</strong>，只能是域名格式 <code>xxx.xxx.xxx</code>。</p><table tabindex="0"><thead><tr><th>证书类型</th><th>域名填写格式</th><th>示例</th></tr></thead><tbody><tr><td><strong>单域名证书</strong></td><td>直接输入需要绑定的域名</td><td><code>yourdomain.com</code> 或 <code>sub.yourdomain.com</code></td></tr><tr><td><strong>通配符证书</strong></td><td><code>*.yourdomain.com</code></td><td><code>*.example.com</code></td></tr><tr><td><strong>多域名SAN证书</strong></td><td>输入一个主域名即可，其它域名在提交证书时输入</td><td><code>example.com</code></td></tr></tbody></table><h3 id="_2-2-常见填写错误" tabindex="-1">2.2 常见填写错误 <a class="header-anchor" href="#_2-2-常见填写错误" aria-label="Permalink to &quot;2.2 常见填写错误&quot;">​</a></h3><p><strong>错误1：填写IP地址</strong></p><ul><li>现象：Save后Submit时出现报错</li><li>原因：SSL证书只能绑定域名，不能绑定IP</li><li>解决：修改为正确的域名格式</li></ul><p><strong>错误2：通配符证书填写具体域名</strong></p><ul><li>现象：提交时提示格式错误</li><li>原因：通配符证书必须填写 <code>*.domain.com</code> 格式</li><li>解决：修改为通配符格式</li></ul><hr><h2 id="三、邮件验证方式" tabindex="-1">三、邮件验证方式 <a class="header-anchor" href="#三、邮件验证方式" aria-label="Permalink to &quot;三、邮件验证方式&quot;">​</a></h2><h3 id="_3-1-操作步骤" tabindex="-1">3.1 操作步骤 <a class="header-anchor" href="#_3-1-操作步骤" aria-label="Permalink to &quot;3.1 操作步骤&quot;">​</a></h3><p><strong>步骤1：选择验证方式</strong></p><ol><li>在证书申请页面填写Domain信息</li><li>选择DCV method “admin@emailtest.raksmart.c”</li><li>点击Save保存</li><li>点击Submit提交</li></ol><p><img src="'+l+'" alt=""></p><p><strong>步骤2：确认提交</strong></p><ul><li>提交成功后，页面会跳转到确认页面</li></ul><p><img src="'+i+'" alt=""></p><p><strong>步骤3：查收邮件并验证</strong></p><ol><li>登录您的邮箱，查收来自证书颁发机构的验证邮件</li><li>邮件中包含验证码（Code）和验证链接</li><li>点击邮件中的 <strong>&quot;here&quot; 链接</strong>，打开验证页面</li><li>在验证页面输入邮件中的验证码，点击 <strong>Next</strong> 完成验证</li></ol><p><img src="'+s+'" alt=""></p><p><img src="'+d+'" alt=""></p><p><img src="'+n+'" alt=""></p><h3 id="_3-2-验证完成" tabindex="-1">3.2 验证完成 <a class="header-anchor" href="#_3-2-验证完成" aria-label="Permalink to &quot;3.2 验证完成&quot;">​</a></h3><ul><li>页面显示验证成功</li><li>证书状态更新为验证通过</li></ul><hr><h2 id="四、dns验证方式" tabindex="-1">四、DNS验证方式 <a class="header-anchor" href="#四、dns验证方式" aria-label="Permalink to &quot;四、DNS验证方式&quot;">​</a></h2><h3 id="_4-1-操作步骤" tabindex="-1">4.1 操作步骤 <a class="header-anchor" href="#_4-1-操作步骤" aria-label="Permalink to &quot;4.1 操作步骤&quot;">​</a></h3><p><strong>步骤1：选择验证方式</strong></p><ol><li>填写Domain信息</li><li>选择DCV method为 <strong>&quot;<strong>DNS validation</strong>&quot;</strong></li><li>点击Save保存</li><li>点击Submit提交</li></ol><p><img src="'+c+'" alt=""></p><p><strong>步骤2：获取验证信息</strong> 提交后，系统会生成DNS验证记录，包含：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>Host</strong></td><td>主机记录</td><td><code>_dnsauth.yourdomain.com</code></td></tr><tr><td><strong>Type</strong></td><td>记录类型</td><td><code>CNAME</code></td></tr><tr><td><strong>Value</strong></td><td>记录值</td><td><code>_dnsauth.yourdomain.com.xxx.xxx.com</code></td></tr></tbody></table><p><strong>步骤3：在DNS管理中添加记录</strong></p><ol><li>登录您的域名DNS管理后台</li><li>找到需要验证的域名，在子域名里填写验证值</li><li>按照系统提供的信息填写：</li></ol><p><img src="'+h+'" alt=""></p><p><strong>步骤3.1：验证DNS解析生效</strong></p><p>添加DNS记录后，可通过DNS检测工具确认解析是否已生效：</p><p>访问 <a href="https://www.racent.com/dns-check" target="_blank" rel="noreferrer">DNS查询_DNS解析记录查询</a> ，输入您的域名和主机记录，查询解析状态。若显示已生效，系统将自动完成证书验证。</p><hr><h2 id="五、http-https验证方式" tabindex="-1">五、HTTP/HTTPS验证方式 <a class="header-anchor" href="#五、http-https验证方式" aria-label="Permalink to &quot;五、HTTP/HTTPS验证方式&quot;">​</a></h2><h3 id="_5-1-操作步骤" tabindex="-1">5.1 操作步骤 <a class="header-anchor" href="#_5-1-操作步骤" aria-label="Permalink to &quot;5.1 操作步骤&quot;">​</a></h3><p><strong>步骤1：选择验证方式</strong></p><ol><li>填写Domain信息</li><li>选择DCV method为 <strong>&quot;<strong>HTTP validation</strong>&quot;</strong></li><li>点击Save保存</li><li>点击Submit提交</li></ol><p><img src="'+g+'" alt=""></p><p><strong>步骤2：获取验证文件信息</strong> 系统会生成一个验证文件，需要在网站根目录创建：</p><table tabindex="0"><thead><tr><th>项目</th><th>内容示例</th></tr></thead><tbody><tr><td><strong>文件路径</strong></td><td><code>/.well-known/pki-validation/文件名.txt</code></td></tr><tr><td><strong>文件内容</strong></td><td><code>验证码 颁发机构域名</code></td></tr><tr><td><strong>验证URL</strong></td><td><code>&lt;http://yourdomain.com/.well-known/pki-validation/文件名.txt</code>&gt;</td></tr></tbody></table><p><strong>步骤3：在网站根目录创建验证文件</strong></p><p><strong>Linux/Apache/Nginx 环境操作示例：</strong></p><p><code># 进入网站根目录（根据实际情况调整路径） cd /var/www/html</code></p><p><code># 创建所需目录 mkdir -p .well-known/pki-validation</code></p><p><code># 进入目录 cd .well-known/pki-validation</code></p><p><code># 创建验证文件并写入内容 echo &quot;205acf83f2718baa25ead1cd95bb2891b8e2c4818586a5bea3046f16b37b080f comodoca.com&quot; &gt; 007BDDFAC9157321D1071420BE72FEA8.txt</code></p><p><code># 设置文件权限（确保可访问） chmod 644 007BDDFAC9157321D1071420BE72FEA8.txt</code></p><p><code># 重启Web服务（可选，使配置生效） /etc/init.d/apache2 restart</code></p><p><code># 或 systemctl restart nginx</code></p><p><strong>Windows/IIS 环境操作：</strong></p><ol><li>在网站根目录下创建文件夹 <code>.well-known</code></li><li>在 <code>.well-known</code> 下创建文件夹 <code>pki-validation</code></li><li>在 <code>pki-validation</code> 文件夹中创建文本文件，文件名如 <code>007BDDFAC9157321D1071420BE72FEA8.txt</code></li><li>用记事本打开文件，粘贴系统提供的内容</li><li>保存文件</li></ol><p><strong>步骤4：测试文件是否可访问</strong> 在浏览器中访问验证URL：</p><ul><li>✅ <strong>正常情况</strong>：浏览器显示文件内容</li><li>❌ <strong>异常情况</strong>：404 Not Found 或无法访问</li></ul><h3 id="_5-2-验证完成" tabindex="-1">5.2 验证完成 <a class="header-anchor" href="#_5-2-验证完成" aria-label="Permalink to &quot;5.2 验证完成&quot;">​</a></h3><ul><li>文件可正常访问后，系统会自动检测并完成验证</li></ul><p><strong>证书验证生效时间：以上验证方式完成后，SSL证书通常在30分钟左右完成签发生效。</strong></p><hr><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h2><h3 id="_6-1-申请后一直未签发怎么办" tabindex="-1">6.1 申请后一直未签发怎么办？ <a class="header-anchor" href="#_6-1-申请后一直未签发怎么办" aria-label="Permalink to &quot;6.1 申请后一直未签发怎么办？&quot;">​</a></h3><p>如果证书长时间处于&quot;申请中(Pending)&quot;状态，可尝试以下操作：</p><ol><li>访问证书状态检查工具：<strong>Sectigo Order Status Checker</strong></li><li>选择已购买的证书订单</li><li>在DCV验证信息页面，找到两项验证配置</li><li><strong>先修改为其他选项</strong>，点击 <strong>Save your changes</strong></li><li><strong>再改回原选项</strong>，再次点击 <strong>Save your changes</strong></li><li>如果配置无误，一般会即时生效</li></ol><h3 id="_6-2-证书申请过程中填写错误怎么办" tabindex="-1">6.2 证书申请过程中填写错误怎么办？ <a class="header-anchor" href="#_6-2-证书申请过程中填写错误怎么办" aria-label="Permalink to &quot;6.2 证书申请过程中填写错误怎么办？&quot;">​</a></h3><ul><li><strong>申请中（Pending）状态</strong>：无法更换域名，需等待签发或取消后重新申请</li><li><strong>已签发（Issued）状态</strong>：可在后台点击 <strong>Replace</strong> 更换域名</li></ul><p><img src="'+p+'" alt=""></p><h3 id="_6-3-误点了取消按钮怎么办" tabindex="-1">6.3 误点了取消按钮怎么办？ <a class="header-anchor" href="#_6-3-误点了取消按钮怎么办" aria-label="Permalink to &quot;6.3 误点了取消按钮怎么办？&quot;">​</a></h3><p><img src="'+u+'" alt=""></p><p><strong>取消状态（Cancelled）说明：</strong></p><ul><li>取消状态无法恢复</li><li>无法进行任何操作</li><li>需要重新购买证书</li></ul><hr><h2 id="七、技术支持" tabindex="-1">七、技术支持 <a class="header-anchor" href="#七、技术支持" aria-label="Permalink to &quot;七、技术支持&quot;">​</a></h2><p>如遇到验证问题，可通过以下方式联系我们：</p><ul><li><strong>提交工单</strong>：后台右上角点击&quot;提交工单&quot;</li></ul>',84)])])}const P=o(m,[["render",b]]);export{D as __pageData,P as default};
